import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"What can OrbySystems do?","description":"","frontmatter":{"title":"What can OrbySystems do?"},"headers":[],"relativePath":"docs/overview/what-can-orby-do.md","filePath":"docs/overview/what-can-orby-do.md","lastUpdated":1793223206000}'),n={name:"docs/overview/what-can-orby-do.md"};function s(i,a,l,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="what-can-orbysystems-do" tabindex="-1">What can OrbySystems do? <a class="header-anchor" href="#what-can-orbysystems-do" aria-label="Permalink to &quot;What can OrbySystems do?&quot;">​</a></h1><h2 id="chat-over-your-data" tabindex="-1">Chat over your data <a class="header-anchor" href="#chat-over-your-data" aria-label="Permalink to &quot;Chat over your data&quot;">​</a></h2><p>Ask questions in plain language and get answers grounded in your actual data — plain text, a data table, or a chart, whichever fits the question best.</p><h2 id="personal-finance-end-to-end" tabindex="-1">Personal finance, end to end <a class="header-anchor" href="#personal-finance-end-to-end" aria-label="Permalink to &quot;Personal finance, end to end&quot;">​</a></h2><ul><li><strong>Spending &amp; income</strong> — every transaction auto-categorized, with recipes for spending trends, recurring bills, top merchants, and more.</li><li><strong>Investment</strong> — track brokerage holdings, allocation, and performance.</li><li><strong>Assets &amp; liabilities</strong> — manually track a house, a car, or other assets, plus the loans against them, with automatic principal/interest tracking on linked payments.</li><li><strong>Combined finance</strong> — bring everything together into one net worth and debt picture across all your accounts.</li></ul><p>See the <a href="/docs/personal-finance/types-of-finance-projects">Personal Finance</a> section for details.</p><h2 id="recipes-and-dashboards" tabindex="-1">Recipes and dashboards <a class="header-anchor" href="#recipes-and-dashboards" aria-label="Permalink to &quot;Recipes and dashboards&quot;">​</a></h2><p>Pre-built charts and breakdowns for the questions you&#39;ll ask often, with drill-downs into the details behind any number. See <a href="/docs/getting-started/browse-recipes">Browse Recipes</a>.</p><h2 id="getting-your-data-in" tabindex="-1">Getting your data in <a class="header-anchor" href="#getting-your-data-in" aria-label="Permalink to &quot;Getting your data in&quot;">​</a></h2><ul><li><strong>Statement Agents</strong> — bring statements from your bank into a project without downloading them by hand. You sign in yourself; agents never act on your accounts.</li><li><strong>Add New Institution</strong> — get a parser for a bank or brokerage statement OrbySystems doesn&#39;t read yet, or fix one that reads a statement wrongly, from a scrambled copy that keeps your data private.</li><li><strong>Transactions Extractor</strong> — parses bank and brokerage statements (PDF, CSV, spreadsheet) into clean transaction data, and lets you check a file before adding it.</li></ul><h2 id="privacy-tools" tabindex="-1">Privacy tools <a class="header-anchor" href="#privacy-tools" aria-label="Permalink to &quot;Privacy tools&quot;">​</a></h2><ul><li><strong>PII Redactor</strong> — strip personal information out of a document before sharing or saving it elsewhere.</li></ul><h2 id="model-tools" tabindex="-1">Model tools <a class="header-anchor" href="#model-tools" aria-label="Permalink to &quot;Model tools&quot;">​</a></h2><ul><li><strong>Model Test</strong> — check that a model you&#39;ve configured works correctly with OrbySystems.</li></ul><p>See the <a href="/docs/tools/statement-agents">Tools</a> section for a full walkthrough of each.</p>',15)])])}const p=e(n,[["render",s]]);export{g as __pageData,p as default};
